Here's a simplified simulation of a Deployment's reconciliation loop and a Service routing to whatever pods currently match its label selector:

```python
class Pod:
    _next_id = 1

    def __init__(self, labels):
        self.id = f"pod-{Pod._next_id}"
        Pod._next_id += 1
        self.labels = labels
        self.healthy = True

class Deployment:
    def __init__(self, desired_replicas, labels):
        self.desired_replicas = desired_replicas
        self.labels = labels
        self.pods = [Pod(labels) for _ in range(desired_replicas)]

    def reconcile(self):
        # drop unhealthy pods, then top back up to the desired count
        self.pods = [p for p in self.pods if p.healthy]
        while len(self.pods) < self.desired_replicas:
            self.pods.append(Pod(self.labels))
        return [p.id for p in self.pods]

class Service:
    def __init__(self, selector_labels):
        self.selector_labels = selector_labels

    def route(self, all_pods):
        # a Service always targets whatever pods currently match its selector
        return [p.id for p in all_pods if p.labels == self.selector_labels]

api_labels = {"app": "api"}
deployment = Deployment(desired_replicas=3, labels=api_labels)
service = Service(selector_labels=api_labels)

print("initial pods:", [p.id for p in deployment.pods])
print("service routes to:", service.route(deployment.pods))

# a node failure kills pod-2
for p in deployment.pods:
    if p.id == "pod-2":
        p.healthy = False

surviving = deployment.reconcile()
print("after reconcile:", surviving)  # pod-2 replaced by pod-4, count back to 3
print("service routes to:", service.route(deployment.pods))  # follows automatically
```

The Service never had to be told a pod died. `reconcile()` keeps the pod count at the declared desired state, and `route()` recomputes its target list by matching labels every time — the same pattern real Kubernetes uses. If `pod-2` is removed and `pod-4` is created with the same `api_labels`, the Service's route immediately includes `pod-4` and excludes `pod-2` with zero manual reconfiguration.

Here's a simplified simulation showing a ConfigMap update reaching a running pod, contrasted with an `emptyDir` volume being wiped when the pod is deleted:

```python
class ConfigMap:
    def __init__(self, data):
        self.data = dict(data)

class Pod:
    def __init__(self, config_map, use_empty_dir=True):
        self.config_map = config_map  # reference, not a copy
        self.empty_dir = {} if use_empty_dir else None

    def read_config(self, key):
        return self.config_map.data.get(key)

    def write_scratch(self, key, value):
        self.empty_dir[key] = value

    def delete(self):
        self.empty_dir = None  # emptyDir is wiped when the pod is deleted

app_config = ConfigMap({"log_level": "info", "max_connections": "100"})
pod = Pod(app_config)

print("log_level before update:", pod.read_config("log_level"))
app_config.data["log_level"] = "debug"  # update the ConfigMap object itself
print("log_level after update:", pod.read_config("log_level"))  # picks it up, same reference

pod.write_scratch("temp_cache_key", "abc123")
print("scratch before delete:", pod.empty_dir)
pod.delete()
print("scratch after delete:", pod.empty_dir)  # gone
```

Because `pod.config_map` holds a reference to the same `ConfigMap` object rather than a copy, updating `app_config.data` is visible through `pod.read_config()` immediately — `"debug"`, not `"info"`. The `emptyDir` scratch space behaves the opposite way: it holds `{"temp_cache_key": "abc123"}` right up until `pod.delete()` runs, at which point it becomes `None` — nothing persists it anywhere.
